parameters.functionCode:
const userData = $input.first().json;

// Check subscription status
if (!userData || userData.length === 0) {
  return {
    error: 'Invalid session or expired subscription',
    code: 'SUBSCRIPTION_INVALID'
  };
}

const user = userData[0];
const now = new Date();
const expiresAt = new Date(user.expires_at);

// Check if subscription is expired
if (now > expiresAt) {
  return {
    error: 'Subscription expired',
    code: 'SUBSCRIPTION_EXPIRED',
    expires_at: user.expires_at
  };
}

// Check message limits
if (user.messages_used >= user.messages_limit) {
  return {
    error: 'Monthly message limit reached',
    code: 'LIMIT_REACHED',
    messages_used: user.messages_used,
    messages_limit: user.messages_limit
  };
}

// All checks passed
return {
  valid: true,
  user_id: user.id,
  plan_type: user.plan_type,
  messages_remaining: user.messages_limit - user.messages_used,
  chatbot_id: $node["Chat Message Received"].json.chatbot_id,
  message: $node["Chat Message Received"].json.message
};

const errorData = $input.first().json;

if (errorData.code === 'SUBSCRIPTION_INVALID') {
  return {
    response: {
      message: 'Please log in or subscribe to access this chatbot.',
      action: 'redirect_to_login',
      upgrade_url: '/subscribe'
    }
  };
}

if (errorData.code === 'SUBSCRIPTION_EXPIRED') {
  return {
    response: {
      message: 'Your subscription has expired. Please renew to continue.',
      action: 'redirect_to_billing',
      renewal_url: '/billing/renew'
    }
  };
}

if (errorData.code === 'LIMIT_REACHED') {
  return {
    response: {
      message: `You've reached your monthly limit of ${errorData.messages_limit} messages. Upgrade for more access.`,
      action: 'upgrade_prompt',
      upgrade_url: '/subscribe/upgrade'
    }
  };
}

return {
  response: {
    message: 'An error occurred. Please try again later.',
    action: 'error'
  }
};

