const aiResponse = $node['Generate AI Response'].json;
const userLimits = $node['Check Message Limits'].json;

return {
  success: true,
  message: aiResponse.choices[0].message.content,
  timestamp: new Date().toISOString(),
  usage: {
    tokens_used: aiResponse.usage.total_tokens,
    messages_remaining: userLimits.messages_remaining - 1
  },
  sources: $node['Query Vector Database'].json.matches.map(match => ({
    source: match.metadata.source,
    relevance: match.score
  }))
};

const errorInfo = $node['Handle Subscription Error'].json;

return {
  success: false,
  error: errorInfo.response.message,
  action: errorInfo.response.action,
  upgrade_url: errorInfo.response.upgrade_url || errorInfo.response.renewal_url,
  timestamp: new Date().toISOString()
};
